double alpha = sd_config.alpha;
double min_cos = sd_config.minimum_cosine;
double reacq_cos = sd_config.reacquire_min_cosine;
unint32 max_rej = sd_config.max_rejects;
unint32 reacq_cfm = sd_config.reacquire_confirm;
adcs_vec3_t unit;
adcs_status_t st;

/* 默认输出初值 */
sd_output.accepted = 0;
sd_output.cosine = 0.0;
sd_output.innovation_rad = 0.0;
sd_output.reference = sd_state.reference;
sd_output.rejects = sd_state.rejects;
sd_output.mode = sd_state.mode;

/* 1. 配置校验（每次调用） */
if ((sd_input.enable != 0 && sd_input.enable != 1) ||
    (!isfinite(alpha)) || (alpha <= 0.0) || (alpha > 1.0) ||
    (!isfinite(min_cos)) || (min_cos < -1.0) || (min_cos > 1.0) ||
    (max_rej < 1U) || (max_rej > 20U) ||
    (!isfinite(reacq_cos)) || (reacq_cos < -1.0) || (reacq_cos > 1.0) ||
    (reacq_cfm < 1U) || (reacq_cfm > 20U)) {
    sd_state.mode = SD_FAULT;
    sd_output.mode = SD_FAULT;
    sd_output.accepted = 0;
    sd_output.cosine = 0.0;
    sd_output.innovation_rad = 0.0;
    sd_output.rejects = sd_state.rejects;
    sd_output.reference = sd_state.reference;
    return;
}

/* 2. disable 清空一切 */
if (sd_input.enable == 0) {
    sd_state.mode = SD_OFF;
    sd_state.initialized = 0;
    sd_state.rejects = 0U;
    sd_state.reacquire_count = 0U;
    sd_state.reference = (adcs_vec3_t){0.0, 0.0, 0.0};
    sd_output.mode = SD_OFF;
    sd_output.accepted = 0;
    sd_output.rejects = 0U;
    sd_output.cosine = 0.0;
    sd_output.innovation_rad = 0.0;
    sd_output.reference = sd_state.reference;
    return;
}

